def elemental_descriptor_table(max_Za: int = MAX_ATOMIC_NUMBER) -> Tensor:
    """Return a float32 buffer of shape ``(max_Za + 1, 31)``."""
    if max_Za < 1 or max_Za > MAX_ATOMIC_NUMBER:
        raise ValueError(
            f"FACTO elemental descriptors cover Z=1..{MAX_ATOMIC_NUMBER}, "
            f"got max_Za={max_Za}"
        )
    table = torch.tensor(_TABLE, dtype=torch.float32)
    return table[: max_Za + 1].contiguous()
